UnityEditor.EditorApplication.delayCall += () => {try{
UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/StreetLoopReverse.unity");var temps=new List<GameObject>();var cs=new List<MeshCollider>();foreach(var item in Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("Docs/SurgicalTracks/baseline-meshes.json"))){var go=new GameObject("Temporary baseline collider");go.layer=31;var mf=GameObject.Find((string)item["name"]).GetComponent<MeshFilter>();go.transform.SetPositionAndRotation(mf.transform.position,mf.transform.rotation);go.transform.localScale=mf.transform.lossyScale;var c=go.AddComponent<MeshCollider>();c.sharedMesh=UnityEditor.AssetDatabase.LoadAssetAtPath<Mesh>(UnityEditor.AssetDatabase.GUIDToAssetPath((string)item["guid"]));cs.Add(c);temps.Add(go);}Physics.SyncTransforms();var branch=UnityEngine.Object.FindObjectsByType<Racer.WoodlandRoute>().Single(b=>b.title=="Laurel Switchbacks");var rows=new List<string>();for(float s=200;s<branch.Length-35;s+=10){var p=branch.At(s,out _);float y=-999;foreach(var c in cs)if(c.Raycast(new Ray(p+Vector3.up*200,Vector3.down),out var h,400))y=Mathf.Max(y,h.point.y);rows.Add($"{s:F1} {p} ground={y:F3} delta={p.y-y:F3}");}foreach(var go in temps)UnityEngine.Object.DestroyImmediate(go);System.IO.File.WriteAllLines("Docs/SurgicalTracks/approach-support.txt",rows);
}catch(Exception e){System.IO.File.WriteAllText("Docs/SurgicalTracks/support-error.txt",e.ToString());}};return "Scheduled approach support check";
